#!/usr/bin/env bash
# workflow-14.sh — 发表之后：归档、传播与被质疑的应对 (Decay risk: medium) SOP walkthrough for 科研方法与论文发表.
# Auto-generated by cli_writer.py. Source: research/03-workflows.md.
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${SCRIPT_DIR}/../lib/common.sh"

INDUSTRY="科研方法与论文发表"
WORKFLOW="发表之后：归档、传播与被质疑的应对 (Decay risk: medium)"

usage() {
  cat <<EOF
workflow-14.sh — Walk through "${WORKFLOW}" SOP for ${INDUSTRY}

逐步走完这个工作流的入门 SOP, 然后做失败模式自检, 输出走查报告。

USAGE:
  ./workflow-14.sh             # interactive
  ./workflow-14.sh --dry-run
  ./workflow-14.sh --json
  ./workflow-14.sh --explain
  ./workflow-14.sh --help
